<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import NxAlert from '../../components/ui/NxAlert.vue';import NxBadge from '../../components/ui/NxBadge.vue';import NxButton from '../../components/ui/NxButton.vue';import NxModal from '../../components/ui/NxModal.vue';import NxPageHeader from '../../components/ui/NxPageHeader.vue';import NxToolbar from '../../components/ui/NxToolbar.vue';
import { applyCoreRouter,applyFrrRouter,getCoreRuntime,getFrrRuntime,getRouters,saveCoreRouter,saveFrrRouter,scanCoreHostKey,trustCoreHostKey } from './api';
const tab=ref<'core'|'frr'>('core');const loading=ref(false);const saving=ref(false);const error=ref('');const notice=ref('');const coreHash=ref('');const frrHash=ref('');const coreSaved=ref(false);const frrSaved=ref(false);const coreTrusted=ref(false);const coreDirty=ref(false);const frrDirty=ref(false);const corePreview=ref('Save a draft to generate the configuration.');const frrPreview=ref('Save a draft to generate the configuration.');const coreRuntime=ref('Use Refresh Runtime after the host key is trusted.');const frrRuntime=ref('Use Refresh Runtime to read the BNG FRR configuration.');const pending=ref<'trust'|'apply-core'|'apply-frr'|null>(null);const fingerprint=ref('');const confirmation=ref('');const dialogError=ref('');
const core=reactive<Record<string,string|number>>({});const frr=reactive<Record<string,string|number>>({});
const coreFields=[['host','Management IP / host','text','10.0.15.6'],['port','SSH port','number','22'],['username','Username','text','root'],['password','Password','password','Leave blank to keep saved password'],['autonomous_system','Local AS','number','65000'],['default_next_hop','Default next hop','text','10.0.26.1'],['public_prefix','Public prefix','text','126.209.31.168/29'],['bng_next_hop','BNG next hop','text','10.255.255.2'],['bgp_group','BGP group','text','BNG'],['local_address','BGP local address','text','10.255.255.1'],['peer_as','Peer AS','number','65001'],['neighbor','BGP neighbor','text','10.255.255.2'],['interface_name','BNG link interface','text','xe-0/1/6'],['interface_description','Interface description','text','LINK TO BNG SERVER'],['interface_address','Interface address','text','10.255.255.1/30']] as const;
const frrFields=[['autonomous_system','Local AS','65001'],['router_id','Router ID','10.255.255.2'],['neighbor','BGP neighbor','10.255.255.1'],['remote_as','Remote AS','65000'],['subscriber_network','Subscriber network','100.64.0.0/24'],['in_prefix_list','Inbound prefix list','PL-DEFAULT'],['out_prefix_list','Outbound prefix list','PL-SUBS'],['in_route_map','Inbound route map','RM-IN-DEFAULT'],['out_route_map','Outbound route map','RM-OUT-SUBS']] as const;
function clear(){error.value='';notice.value='';dialogError.value='';}
async function load(show=false){loading.value=true;clear();try{const r=await getRouters();const c={...(r.core_defaults||{}),...(r.core?.config||{}),...(r.core||{})};const f={...(r.frr_defaults||{}),...(r.frr?.config||{})};delete c.password;delete c.known_host_key;Object.keys(core).forEach(k=>delete core[k]);Object.keys(frr).forEach(k=>delete frr[k]);Object.entries(c).forEach(([k,v])=>core[k]=String(v??''));Object.entries(f).forEach(([k,v])=>frr[k]=String(v??''));corePreview.value=r.core?.rendered_config||'Save a draft to generate the configuration.';frrPreview.value=r.frr?.rendered_config||'Save a draft to generate the configuration.';coreHash.value=r.core_hash||'';frrHash.value=r.frr_hash||'';coreSaved.value=Boolean(r.core?.id);frrSaved.value=Boolean(r.frr?.id);coreTrusted.value=Boolean(r.core?.host_key_trusted);coreDirty.value=false;frrDirty.value=false;if(show)notice.value='Router drafts refreshed.';}catch(reason){error.value=reason instanceof Error?reason.message:'Failed to load routers.';}finally{loading.value=false;}}
async function save(type:'core'|'frr'){saving.value=true;clear();try{const result=type==='core'?await saveCoreRouter({...core,enabled:1}):await saveFrrRouter({...frr,enabled:1});notice.value=result.message;await load(false);}catch(reason){error.value=reason instanceof Error?reason.message:'Failed to save router draft.';}finally{saving.value=false;}}
async function runtime(type:'core'|'frr'){clear();if(type==='core')coreRuntime.value='Loading…';else frrRuntime.value='Loading…';try{const r=type==='core'?await getCoreRuntime():await getFrrRuntime();if(type==='core')coreRuntime.value=r.output||r.error||'No output returned.';else frrRuntime.value=r.output||r.error||'No output returned.';}catch(reason){const m=reason instanceof Error?reason.message:'Runtime read failed.';if(type==='core')coreRuntime.value=m;else frrRuntime.value=m;error.value=m;}}
async function requestTrust(){clear();try{fingerprint.value=(await scanCoreHostKey()).fingerprint;confirmation.value='';pending.value='trust';}catch(reason){error.value=reason instanceof Error?reason.message:'Unable to scan host key.';}}
function requestApply(type:'core'|'frr'){confirmation.value='';dialogError.value='';pending.value=type==='core'?'apply-core':'apply-frr';}
async function execute(){if(!pending.value)return;const phrase=pending.value==='trust'?fingerprint.value:pending.value==='apply-core'?'APPLY CORE ROUTER CONFIG':'APPLY FRR ROUTER CONFIG';if(confirmation.value!==phrase){dialogError.value=`Type ${phrase} exactly to continue.`;return;}saving.value=true;try{let message='';if(pending.value==='trust')message=(await trustCoreHostKey(fingerprint.value)).message;if(pending.value==='apply-core')message=(await applyCoreRouter(coreHash.value)).message;if(pending.value==='apply-frr')message=(await applyFrrRouter(frrHash.value)).message;const applied=pending.value;pending.value=null;notice.value=message;if(applied==='apply-core')await runtime('core');if(applied==='apply-frr')await runtime('frr');await load(false);}catch(reason){dialogError.value=reason instanceof Error?reason.message:'Router action failed.';}finally{saving.value=false;}}
onMounted(()=>void load(false));
</script>
<template><div class="space-y-4 pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="Routing infrastructure" title="Routers" description="Manage the Juniper backbone router and the FRRouting instance running on the BNG server."><template #actions><NxButton variant="secondary" :disabled="loading" @click="load(true)">{{loading?'Refreshing…':'Refresh Drafts'}}</NxButton></template></NxPageHeader><NxAlert v-if="error||notice" :tone="error?'danger':'success'">{{error||notice}}</NxAlert><NxToolbar><div role="tablist" class="flex gap-2"><button class="min-h-10 rounded-md px-4 text-sm font-semibold" :class="tab==='core'?'bg-brand-600 text-white':'bg-[var(--nx-surface-muted)]'" @click="tab='core'">Core Router</button><button class="min-h-10 rounded-md px-4 text-sm font-semibold" :class="tab==='frr'?'bg-brand-600 text-white':'bg-[var(--nx-surface-muted)]'" @click="tab='frr'">FRR Router</button></div></NxToolbar>
<section v-if="tab==='core'" class="overflow-hidden rounded-lg border border-[var(--nx-border)] bg-[var(--nx-surface)] shadow-sm"><header class="flex flex-wrap items-start justify-between gap-3 border-b border-[var(--nx-border)] p-5"><div><div class="flex items-center gap-2"><h2 class="font-bold">Juniper Core Router</h2><NxBadge :tone="coreSaved?'success':'neutral'">{{coreSaved?'DRAFT SAVED':'NOT SAVED'}}</NxBadge></div><p class="text-sm text-[var(--nx-text-muted)]">Backbone BGP peering, public-prefix route, and physical BNG link.</p></div><div class="flex gap-2"><NxButton variant="secondary" :disabled="!coreSaved" @click="requestTrust">Trust Host Key</NxButton><NxButton variant="secondary" :disabled="!coreSaved||!coreTrusted" @click="runtime('core')">Refresh Runtime</NxButton></div></header><form class="p-5" @submit.prevent="save('core')" @input="coreDirty=true"><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><label v-for="field in coreFields" :key="field[0]" class="grid gap-1.5 text-sm font-semibold">{{field[1]}}<input v-model="core[field[0]]" :type="field[2]" :placeholder="field[3]" :required="field[0]!=='password'" class="min-h-11 rounded-md bg-[var(--nx-surface-muted)] px-3 font-normal"></label></div><div class="mt-5 flex justify-end gap-2 border-t border-[var(--nx-border)] pt-4"><NxButton type="submit" :disabled="saving">Save Draft</NxButton><NxButton type="button" variant="danger" :disabled="!coreSaved||!coreHash||coreDirty" @click="requestApply('core')">Apply to Core Router</NxButton></div></form><div class="grid border-t border-[var(--nx-border)] xl:grid-cols-2"><div class="border-b border-[var(--nx-border)] xl:border-b-0 xl:border-r"><h3 class="p-3 font-semibold">Generated Junos configuration</h3><pre class="m-0 max-h-96 overflow-auto bg-slate-950 p-4 text-xs text-slate-100">{{corePreview}}</pre></div><div><h3 class="p-3 font-semibold">Live runtime</h3><pre class="m-0 max-h-96 overflow-auto bg-slate-950 p-4 text-xs text-slate-100">{{coreRuntime}}</pre></div></div></section>
<section v-if="tab==='frr'" class="overflow-hidden rounded-lg border border-[var(--nx-border)] bg-[var(--nx-surface)] shadow-sm"><header class="flex flex-wrap items-start justify-between gap-3 border-b border-[var(--nx-border)] p-5"><div><div class="flex items-center gap-2"><h2 class="font-bold">FRR Router on BNG</h2><NxBadge :tone="frrSaved?'success':'neutral'">{{frrSaved?'DRAFT SAVED':'NOT SAVED'}}</NxBadge></div><p class="text-sm text-[var(--nx-text-muted)]">Uses the trusted BNG SSH connection and runs vtysh locally.</p></div><NxButton variant="secondary" @click="runtime('frr')">Refresh Runtime</NxButton></header><form class="p-5" @submit.prevent="save('frr')" @input="frrDirty=true"><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><label v-for="field in frrFields" :key="field[0]" class="grid gap-1.5 text-sm font-semibold">{{field[1]}}<input v-model="frr[field[0]]" :placeholder="field[2]" required class="min-h-11 rounded-md bg-[var(--nx-surface-muted)] px-3 font-normal"></label></div><div class="mt-5 flex justify-end gap-2 border-t border-[var(--nx-border)] pt-4"><NxButton type="submit" :disabled="saving">Save Draft</NxButton><NxButton type="button" variant="danger" :disabled="!frrSaved||!frrHash||frrDirty" @click="requestApply('frr')">Apply through vtysh</NxButton></div></form><div class="grid border-t border-[var(--nx-border)] xl:grid-cols-2"><div class="border-b border-[var(--nx-border)] xl:border-b-0 xl:border-r"><h3 class="p-3 font-semibold">Generated FRR configuration</h3><pre class="m-0 max-h-96 overflow-auto bg-slate-950 p-4 text-xs text-slate-100">{{frrPreview}}</pre></div><div><h3 class="p-3 font-semibold">Live vtysh runtime</h3><pre class="m-0 max-h-96 overflow-auto bg-slate-950 p-4 text-xs text-slate-100">{{frrRuntime}}</pre></div></div></section>
<NxModal :open="Boolean(pending)" :title="pending==='trust'?'Trust Core Router host key?':pending==='apply-core'?'Apply Core Router configuration?':'Apply FRR Router configuration?'" :description="pending==='trust'?`Verify this Juniper fingerprint through a trusted channel: ${fingerprint}`:'Push and commit this exact saved draft. The saved configuration hash is verified by the backend.'" @close="pending=null"><div class="p-6"><NxAlert v-if="dialogError" tone="danger" class="mb-4">{{dialogError}}</NxAlert><label class="grid gap-2 text-sm font-semibold">Type the confirmation phrase<input v-model="confirmation" class="min-h-11 rounded-md bg-[var(--nx-surface-muted)] px-3 font-mono"></label><p class="mt-2 break-all text-xs text-[var(--nx-text-muted)]">Required: <code>{{pending==='trust'?fingerprint:pending==='apply-core'?'APPLY CORE ROUTER CONFIG':'APPLY FRR ROUTER CONFIG'}}</code></p></div><template #footer><NxButton variant="secondary" @click="pending=null">Cancel</NxButton><NxButton variant="danger" :disabled="saving" @click="execute">{{saving?'Working…':pending==='trust'?'Trust Host Key':'Apply Configuration'}}</NxButton></template></NxModal></div></template>
